# This file was generated by Claude Opus 5.5 on Medium Thinking mode when asked to generate 5-10 metrics for Prometheus for our product in app.py.

# Prometheus metrics for the Image to Safety Advice app, written by Claude Opus 5.5.
# Served by prometheus_client at :8000/metrics (start_http_server is called in app.py)
# and scraped by Prometheus as the 'gradio_app' job.

from prometheus_client import Counter, Gauge, Histogram

# LLM calls can take anywhere from ~1s (remote) to minutes (local on CPU)
LATENCY_BUCKETS = (0.5, 1, 2, 5, 10, 20, 30, 60, 120, 300)

# 1. Requests by model and outcome (status: success / error / no_input)
REQUESTS = Counter(
    "app_requests_total",
    "Safety-advice requests handled, by model platform and outcome",
    ["platform", "status"],
)

# 2. End-to-end latency the user experiences (CLIP + LLM)
REQUEST_DURATION = Histogram(
    "app_request_duration_seconds",
    "End-to-end time to produce safety advice",
    ["platform"],
    buckets=LATENCY_BUCKETS,
)

# 3. Requests currently being processed (queue pressure)
IN_PROGRESS = Gauge(
    "app_requests_in_progress",
    "Safety-advice requests currently being processed",
)

# 4. Time spent in the LLM alone, local vs remote
LLM_DURATION = Histogram(
    "app_llm_generation_seconds",
    "Time spent generating advice in the LLM",
    ["platform"],
    buckets=LATENCY_BUCKETS,
)

# 5. Response length in tokens, local vs remote
LLM_OUTPUT_TOKENS = Histogram(
    "app_llm_output_tokens",
    "Number of tokens generated per LLM response",
    ["platform"],
    buckets=(16, 32, 64, 128, 256, 512, 1024, 2048, 4096),
)

# 6. Time spent on the external CLIP Interrogator Space
CLIP_DURATION = Histogram(
    "app_clip_interrogator_seconds",
    "Time spent calling the CLIP Interrogator to describe the image",
    buckets=LATENCY_BUCKETS,
)

# 7. CLIP failures (fallback: text = used the user's text description, none = nothing to fall back on)
CLIP_FAILURES = Counter(
    "app_clip_failures_total",
    "CLIP Interrogator calls that failed",
    ["fallback"],
)

# 8. How long the local Qwen model took to load at startup
MODEL_LOAD_SECONDS = Gauge(
    "app_model_load_seconds",
    "Time taken to load the local LLM at startup",
)
